typedef struct { uint8_t r, g, b; } ds_rgb;

/* A theme: every color role, and the scrims as ink opacity 0-255. */
typedef struct {
	const char *name;
	ds_rgb ground;
	ds_rgb surface;
	ds_rgb raised;
	ds_rgb edge;
	ds_rgb track;
	ds_rgb text;
	ds_rgb text_soft;
	ds_rgb text_dim;
	ds_rgb accent;
	ds_rgb on_accent;
	ds_rgb accent_ink;
	ds_rgb light;
	ds_rgb favorite;
	ds_rgb warning;
	ds_rgb ink;
	uint8_t scrim_menu;
	uint8_t scrim_game;
	uint8_t bar_shadow;   /* the bar's shadow, ink opacity 0-255 */
} ds_theme;

enum { DS_LIGHT, DS_DARK, DS_THEMES };

