/* out: arriving and moving. Quintic ease-out. */
static inline float ds_out(float t)
{
	t = t < 0 ? 0 : (t > 1 ? 1 : t);
	t = 1 - t;
	return 1 - t * t * t * t * t;
}

/* in: leaving. Cubic ease-in. */
static inline float ds_in(float t)
{
	t = t < 0 ? 0 : (t > 1 ? 1 : t);
	return t * t * t;
}

/* turn: big spatial changes. Smoothstep. */
static inline float ds_turn(float t)
{
	t = t < 0 ? 0 : (t > 1 ? 1 : t);
	return t * t * (3 - 2 * t);
}

/* Sound: each a list of tones, played together from their start times. */
typedef enum { DS_WAVE_SINE, DS_WAVE_TRIANGLE, DS_WAVE_SQUARE } ds_wave;
typedef struct { ds_wave wave; float hz; int ms; float peak; int at_ms; } ds_tone;
typedef enum {
	DS_SOUND_MOVE,
	DS_SOUND_EDGE,
	DS_SOUND_ACCEPT,
	DS_SOUND_BACK,
	DS_SOUND_DENY,
	DS_SOUND_REWARD,
	DS_SOUNDS
} ds_sound;
